arguments.command:
cat > /tmp/stackalloc_nint/Program.cs << 'EOF'
using System;

Span<nint> signed = stackalloc nint[4];
Span<nuint> unsigned = stackalloc nuint[4];

for (int i = 0; i < 4; i++)
{
    signed[i] = i * 10;
    unsigned[i] = (nuint)(i * 20);
}

Console.WriteLine($"nint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
Console.WriteLine($"signed: [{string.Join(", ", signed.ToArray())}]");
Console.WriteLine($"unsigned: [{string.Join(", ", unsigned.ToArray())}]");
EOF
mkdir -p /tmp/stackalloc_nint && cat > /tmp/stackalloc_nint/stackalloc_nint.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
  </PropertyGroup>
</Project>
EOF
cat > /tmp/stackalloc_nint/Program.cs << 'EOF'
using System;

unsafe
{
    Span<nint> signed = stackalloc nint[4];
    Span<nuint> unsigned = stackalloc nuint[4];

    for (int i = 0; i < 4; i++)
    {
        signed[i] = i * 10;
        unsigned[i] = (nuint)(i * 20);
    }

    Console.WriteLine($"nint size: {sizeof(nint)} bytes");
    Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
    Console.WriteLine($"signed: [{string.Join(", ", signed.ToArray())}]");
    Console.WriteLine($"unsigned: [{string.Join(", ", unsigned.ToArray())}]");
}
EOF
dotnet run --project /tmp/stackalloc_nint

